encode_msg_ApproveResult(Msg, TrUserData) -> encode_msg_ApproveResult(Msg, <<>>, TrUserData).


encode_msg_ApproveResult(#{} = M, Bin, TrUserData) ->
    case M of
        #{ok := F1} ->
            begin
                TrF1 = id(F1, TrUserData),
                if TrF1 =:= false -> Bin;
                   true -> e_type_bool(TrF1, <<Bin/binary, 8>>, TrUserData)
                end
            end;
        _ -> Bin
    end.

encode_msg_BrainStatusResult(Msg, TrUserData) -> encode_msg_BrainStatusResult(Msg, <<>>, TrUserData).


encode_msg_BrainStatusResult(#{} = M, Bin, TrUserData) ->
    B1 = case M of
             #{state := F1} ->
                 begin
                     TrF1 = id(F1, TrUserData),
                     case is_empty_string(TrF1) of
                         true -> Bin;
                         false -> e_type_string(TrF1, <<Bin/binary, 10>>, TrUserData)
                     end
                 end;
             _ -> Bin
         end,
    B2 = case M of
             #{loop_count := F2} ->
                 begin
                     TrF2 = id(F2, TrUserData),
                     if TrF2 =:= 0 -> B1;
                        true -> e_type_int32(TrF2, <<B1/binary, 16>>, TrUserData)
                     end
                 end;
             _ -> B1
         end,
    B3 = case M of
             #{max_loops := F3} ->
                 begin
                     TrF3 = id(F3, TrUserData),
                     if TrF3 =:= 0 -> B2;
                        true -> e_type_int32(TrF3, <<B2/binary, 24>>, TrUserData)
                     end
                 end;
             _ -> B2
         end,
    case M of
        #{history_len := F4} ->
            begin
                TrF4 = id(F4, TrUserData),
                if TrF4 =:= 0 -> B3;
                   true -> e_type_int32(TrF4, <<B3/binary, 32>>, TrUserData)
                end
            end;
        _ -> B3
    end.

encode_msg_HistoryEntry(Msg, TrUserData) -> encode_msg_HistoryEntry(Msg, <<>>, TrUserData).


