e_field_GetHistoryResult_messages([], Bin, _TrUserData) -> Bin.

-compile({nowarn_unused_function,e_type_sint/3}).
e_type_sint(Value, Bin, _TrUserData) when Value >= 0 -> e_varint(Value * 2, Bin);
e_type_sint(Value, Bin, _TrUserData) -> e_varint(Value * -2 - 1, Bin).

-compile({nowarn_unused_function,e_type_int32/3}).
e_type_int32(Value, Bin, _TrUserData) when 0 =< Value, Value =< 127 -> <<Bin/binary, Value>>;
e_type_int32(Value, Bin, _TrUserData) ->
    <<N:64/unsigned-native>> = <<Value:64/signed-native>>,
    e_varint(N, Bin).

-compile({nowarn_unused_function,e_type_int64/3}).
e_type_int64(Value, Bin, _TrUserData) when 0 =< Value, Value =< 127 -> <<Bin/binary, Value>>;
e_type_int64(Value, Bin, _TrUserData) ->
    <<N:64/unsigned-native>> = <<Value:64/signed-native>>,
    e_varint(N, Bin).

-compile({nowarn_unused_function,e_type_bool/3}).
e_type_bool(true, Bin, _TrUserData) -> <<Bin/binary, 1>>;
e_type_bool(false, Bin, _TrUserData) -> <<Bin/binary, 0>>;
e_type_bool(1, Bin, _TrUserData) -> <<Bin/binary, 1>>;
e_type_bool(0, Bin, _TrUserData) -> <<Bin/binary, 0>>.

-compile({nowarn_unused_function,e_type_string/3}).
e_type_string(S, Bin, _TrUserData) ->
    Utf8 = unicode:characters_to_binary(S),
    Bin2 = e_varint(byte_size(Utf8), Bin),
    <<Bin2/binary, Utf8/binary>>.

-compile({nowarn_unused_function,e_type_bytes/3}).
e_type_bytes(Bytes, Bin, _TrUserData) when is_binary(Bytes) ->
    Bin2 = e_varint(byte_size(Bytes), Bin),
    <<Bin2/binary, Bytes/binary>>;
e_type_bytes(Bytes, Bin, _TrUserData) when is_list(Bytes) ->
    BytesBin = iolist_to_binary(Bytes),
    Bin2 = e_varint(byte_size(BytesBin), Bin),
    <<Bin2/binary, BytesBin/binary>>.

-compile({nowarn_unused_function,e_type_fixed32/3}).
e_type_fixed32(Value, Bin, _TrUserData) -> <<Bin/binary, Value:32/little>>.

-compile({nowarn_unused_function,e_type_sfixed32/3}).
e_type_sfixed32(Value, Bin, _TrUserData) -> <<Bin/binary, Value:32/little-signed>>.

-compile({nowarn_unused_function,e_type_fixed64/3}).
e_type_fixed64(Value, Bin, _TrUserData) -> <<Bin/binary, Value:64/little>>.

-compile({nowarn_unused_function,e_type_sfixed64/3}).
e_type_sfixed64(Value, Bin, _TrUserData) -> <<Bin/binary, Value:64/little-signed>>.

-compile({nowarn_unused_function,e_type_float/3}).
e_type_float(V, Bin, _) when is_number(V) -> <<Bin/binary, V:32/little-float>>;
e_type_float(infinity, Bin, _) -> <<Bin/binary, 0:16, 128, 127>>;
e_type_float('-infinity', Bin, _) -> <<Bin/binary, 0:16, 128, 255>>;
e_type_float(nan, Bin, _) -> <<Bin/binary, 0:16, 192, 127>>.

-compile({nowarn_unused_function,e_type_double/3}).
e_type_double(V, Bin, _) when is_number(V) -> <<Bin/binary, V:64/little-float>>;
e_type_double(infinity, Bin, _) -> <<Bin/binary, 0:48, 240, 127>>;
e_type_double('-infinity', Bin, _) -> <<Bin/binary, 0:48, 240, 255>>;
e_type_double(nan, Bin, _) -> <<Bin/binary, 0:48, 248, 127>>.

-compile({nowarn_unused_function,e_unknown_elems/2}).
e_unknown_elems([Elem | Rest], Bin) ->
    BinR = case Elem of
               {varint, FNum, N} ->
                   BinF = e_varint(FNum bsl 3, Bin),
                   e_varint(N, BinF);
               {length_delimited, FNum, Data} ->
                   BinF = e_varint(FNum bsl 3 bor 2, Bin),
                   BinL = e_varint(byte_size(Data), BinF),
                   <<BinL/binary, Data/binary>>;
               {group, FNum, GroupFields} ->
                   Bin1 = e_varint(FNum bsl 3 bor 3, Bin),
                   Bin2 = e_unknown_elems(GroupFields, Bin1),
                   e_varint(FNum bsl 3 bor 4, Bin2);
               {fixed32, FNum, V} ->
                   BinF = e_varint(FNum bsl 3 bor 5, Bin),
                   <<BinF/binary, V:32/little>>;
               {fixed64, FNum, V} ->
                   BinF = e_varint(FNum bsl 3 bor 1, Bin),
                   <<BinF/binary, V:64/little>>
           end,
    e_unknown_elems(Rest, BinR);
e_unknown_elems([], Bin) -> Bin.

-compile({nowarn_unused_function,e_varint/3}).
e_varint(N, Bin, _TrUserData) -> e_varint(N, Bin).

-compile({nowarn_unused_function,e_varint/2}).
e_varint(N, Bin) when N =< 127 -> <<Bin/binary, N>>;
e_varint(N, Bin) ->
    Bin2 = <<Bin/binary, (N band 127 bor 128)>>,
    e_varint(N bsr 7, Bin2).

is_empty_string("") -> true;
is_empty_string(<<>>) -> true;
is_empty_string(L) when is_list(L) -> not string_has_chars(L);
is_empty_string(B) when is_binary(B) -> false.

string_has_chars([C | _]) when is_integer(C) -> true;
string_has_chars([H | T]) ->
    case string_has_chars(H) of
        true -> true;
        false -> string_has_chars(T)
    end;
string_has_chars(B) when is_binary(B), byte_size(B) =/= 0 -> true;
string_has_chars(C) when is_integer(C) -> true;
string_has_chars(<<>>) -> false;
string_has_chars([]) -> false.


decode_msg(Bin, MsgName) when is_binary(Bin) -> decode_msg(Bin, MsgName, []).

decode_msg(Bin, MsgName, Opts) when is_binary(Bin) ->
    TrUserData = proplists:get_value(user_data, Opts),
    decode_msg_1_catch(Bin, MsgName, TrUserData).


decode_msg_1_catch(Bin, MsgName, TrUserData) ->
    try decode_msg_2_doit(MsgName, Bin, TrUserData)
    catch
        error:{gpb_error,_}=Reason:StackTrace ->
            erlang:raise(error, Reason, StackTrace);
        Class:Reason:StackTrace ->
            error({gpb_error,
                   {decoding_failure,
                    {Bin, MsgName, {Class, Reason, StackTrace}}}})
    end.

decode_msg_2_doit('PanelFrame', Bin, TrUserData) -> id(decode_msg_PanelFrame(Bin, TrUserData), TrUserData);
decode_msg_2_doit('PanelRequest', Bin, TrUserData) -> id(decode_msg_PanelRequest(Bin, TrUserData), TrUserData);
decode_msg_2_doit('PanelResponse', Bin, TrUserData) -> id(decode_msg_PanelResponse(Bin, TrUserData), TrUserData);
decode_msg_2_doit('PanelStream', Bin, TrUserData) -> id(decode_msg_PanelStream(Bin, TrUserData), TrUserData);
decode_msg_2_doit('LlmChunk', Bin, TrUserData) -> id(decode_msg_LlmChunk(Bin, TrUserData), TrUserData);
decode_msg_2_doit('ToolEvent', Bin, TrUserData) -> id(decode_msg_ToolEvent(Bin, TrUserData), TrUserData);
decode_msg_2_doit('FinalAnswer', Bin, TrUserData) -> id(decode_msg_FinalAnswer(Bin, TrUserData), TrUserData);
decode_msg_2_doit('StreamError', Bin, TrUserData) -> id(decode_msg_StreamError(Bin, TrUserData), TrUserData);
decode_msg_2_doit('StartSessionArgs', Bin, TrUserData) -> id(decode_msg_StartSessionArgs(Bin, TrUserData), TrUserData);
decode_msg_2_doit('SendArgs', Bin, TrUserData) -> id(decode_msg_SendArgs(Bin, TrUserData), TrUserData);
decode_msg_2_doit('ApproveArgs', Bin, TrUserData) -> id(decode_msg_ApproveArgs(Bin, TrUserData), TrUserData);
decode_msg_2_doit('BrainStatusArgs', Bin, TrUserData) -> id(decode_msg_BrainStatusArgs(Bin, TrUserData), TrUserData);
decode_msg_2_doit('GetHistoryArgs', Bin, TrUserData) -> id(decode_msg_GetHistoryArgs(Bin, TrUserData), TrUserData);
decode_msg_2_doit('StartSessionResult', Bin, TrUserData) -> id(decode_msg_StartSessionResult(Bin, TrUserData), TrUserData);
decode_msg_2_doit('SendResult', Bin, TrUserData) -> id(decode_msg_SendResult(Bin, TrUserData), TrUserData);
decode_msg_2_doit('ListToolsResult', Bin, TrUserData) -> id(decode_msg_ListToolsResult(Bin, TrUserData), TrUserData);
decode_msg_2_doit('ToolDesc', Bin, TrUserData) -> id(decode_msg_ToolDesc(Bin, TrUserData), TrUserData);
decode_msg_2_doit('ApproveResult', Bin, TrUserData) -> id(decode_msg_ApproveResult(Bin, TrUserData), TrUserData);
decode_msg_2_doit('BrainStatusResult', Bin, TrUserData) -> id(decode_msg_BrainStatusResult(Bin, TrUserData), TrUserData);
decode_msg_2_doit('HistoryEntry', Bin, TrUserData) -> id(decode_msg_HistoryEntry(Bin, TrUserData), TrUserData);
decode_msg_2_doit('GetHistoryResult', Bin, TrUserData) -> id(decode_msg_GetHistoryResult(Bin, TrUserData), TrUserData);
decode_msg_2_doit('StopResult', Bin, TrUserData) -> id(decode_msg_StopResult(Bin, TrUserData), TrUserData).



decode_msg_PanelFrame(Bin, TrUserData) -> dfp_read_field_def_PanelFrame(Bin, 0, 0, 0, id('$undef', TrUserData), TrUserData).

dfp_read_field_def_PanelFrame(<<10, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> d_field_PanelFrame_request(Rest, Z1, Z2, F, F@_1, TrUserData);
dfp_read_field_def_PanelFrame(<<18, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> d_field_PanelFrame_response(Rest, Z1, Z2, F, F@_1, TrUserData);
dfp_read_field_def_PanelFrame(<<26, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> d_field_PanelFrame_stream(Rest, Z1, Z2, F, F@_1, TrUserData);
dfp_read_field_def_PanelFrame(<<>>, 0, 0, _, F@_1, _) ->
    S1 = #{},
    if F@_1 == '$undef' -> S1;
       true ->
           {Tagpayload, Valuepayload} = F@_1,
           S1#{Tagpayload => Valuepayload}
    end;
dfp_read_field_def_PanelFrame(Other, Z1, Z2, F, F@_1, TrUserData) -> dg_read_field_def_PanelFrame(Other, Z1, Z2, F, F@_1, TrUserData).

dg_read_field_def_PanelFrame(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 32 - 7 -> dg_read_field_def_PanelFrame(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
dg_read_field_def_PanelFrame(<<0:1, X:7, Rest/binary>>, N, Acc, _, F@_1, TrUserData) ->
    Key = X bsl N + Acc,
    case Key of
        10 -> d_field_PanelFrame_request(Rest, 0, 0, 0, F@_1, TrUserData);
        18 -> d_field_PanelFrame_response(Rest, 0, 0, 0, F@_1, TrUserData);
        26 -> d_field_PanelFrame_stream(Rest, 0, 0, 0, F@_1, TrUserData);
        _ ->
            case Key band 7 of
                0 -> skip_varint_PanelFrame(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                1 -> skip_64_PanelFrame(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                2 -> skip_length_delimited_PanelFrame(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                3 -> skip_group_PanelFrame(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                5 -> skip_32_PanelFrame(Rest, 0, 0, Key bsr 3, F@_1, TrUserData)
            end
    end;
dg_read_field_def_PanelFrame(<<>>, 0, 0, _, F@_1, _) ->
    S1 = #{},
    if F@_1 == '$undef' -> S1;
       true ->
           {Tagpayload, Valuepayload} = F@_1,
           S1#{Tagpayload => Valuepayload}
    end.

d_field_PanelFrame_request(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 57 -> d_field_PanelFrame_request(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
d_field_PanelFrame_request(<<0:1, X:7, Rest/binary>>, N, Acc, F, Prev, TrUserData) ->
    {NewFValue, RestF} = begin Len = X bsl N + Acc, <<Bs:Len/binary, Rest2/binary>> = Rest, {id(decode_msg_PanelRequest(Bs, TrUserData), TrUserData), Rest2} end,
    dfp_read_field_def_PanelFrame(RestF,
                                  0,
                                  0,
                                  F,
                                  case Prev of
                                      '$undef' -> id({request, NewFValue}, TrUserData);
                                      {request, MVPrev} -> id({request, merge_msg_PanelRequest(MVPrev, NewFValue, TrUserData)}, TrUserData);
                                      _ -> id({request, NewFValue}, TrUserData)
                                  end,
                                  TrUserData).

d_field_PanelFrame_response(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 57 -> d_field_PanelFrame_response(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
d_field_PanelFrame_response(<<0:1, X:7, Rest/binary>>, N, Acc, F, Prev, TrUserData) ->
    {NewFValue, RestF} = begin Len = X bsl N + Acc, <<Bs:Len/binary, Rest2/binary>> = Rest, {id(decode_msg_PanelResponse(Bs, TrUserData), TrUserData), Rest2} end,
    dfp_read_field_def_PanelFrame(RestF,
                                  0,
                                  0,
                                  F,
                                  case Prev of
                                      '$undef' -> id({response, NewFValue}, TrUserData);
                                      {response, MVPrev} -> id({response, merge_msg_PanelResponse(MVPrev, NewFValue, TrUserData)}, TrUserData);
                                      _ -> id({response, NewFValue}, TrUserData)
                                  end,
                                  TrUserData).

d_field_PanelFrame_stream(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 57 -> d_field_PanelFrame_stream(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
d_field_PanelFrame_stream(<<0:1, X:7, Rest/binary>>, N, Acc, F, Prev, TrUserData) ->
    {NewFValue, RestF} = begin Len = X bsl N + Acc, <<Bs:Len/binary, Rest2/binary>> = Rest, {id(decode_msg_PanelStream(Bs, TrUserData), TrUserData), Rest2} end,
    dfp_read_field_def_PanelFrame(RestF,
                                  0,
                                  0,
                                  F,
                                  case Prev of
                                      '$undef' -> id({stream, NewFValue}, TrUserData);
                                      {stream, MVPrev} -> id({stream, merge_msg_PanelStream(MVPrev, NewFValue, TrUserData)}, TrUserData);
                                      _ -> id({stream, NewFValue}, TrUserData)
                                  end,
                                  TrUserData).

skip_varint_PanelFrame(<<1:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> skip_varint_PanelFrame(Rest, Z1, Z2, F, F@_1, TrUserData);
skip_varint_PanelFrame(<<0:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> dfp_read_field_def_PanelFrame(Rest, Z1, Z2, F, F@_1, TrUserData).

skip_length_delimited_PanelFrame(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 57 -> skip_length_delimited_PanelFrame(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
skip_length_delimited_PanelFrame(<<0:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) ->
    Length = X bsl N + Acc,
    <<_:Length/binary, Rest2/binary>> = Rest,
    dfp_read_field_def_PanelFrame(Rest2, 0, 0, F, F@_1, TrUserData).

skip_group_PanelFrame(Bin, _, Z2, FNum, F@_1, TrUserData) ->
    {_, Rest} = read_group(Bin, FNum),
    dfp_read_field_def_PanelFrame(Rest, 0, Z2, FNum, F@_1, TrUserData).

skip_32_PanelFrame(<<_:32, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> dfp_read_field_def_PanelFrame(Rest, Z1, Z2, F, F@_1, TrUserData).

skip_64_PanelFrame(<<_:64, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> dfp_read_field_def_PanelFrame(Rest, Z1, Z2, F, F@_1, TrUserData).

decode_msg_PanelRequest(Bin, TrUserData) -> dfp_read_field_def_PanelRequest(Bin, 0, 0, 0, id(0, TrUserData), id(<<>>, TrUserData), id(<<>>, TrUserData), TrUserData).

dfp_read_field_def_PanelRequest(<<8, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, F@_3, TrUserData) -> d_field_PanelRequest_id(Rest, Z1, Z2, F, F@_1, F@_2, F@_3, TrUserData);
