dg_read_field_def_StopResult(<<>>, 0, 0, _, F@_1, _) -> #{ok => F@_1}.

d_field_StopResult_ok(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 57 -> d_field_StopResult_ok(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
d_field_StopResult_ok(<<0:1, X:7, Rest/binary>>, N, Acc, F, _, TrUserData) ->
    {NewFValue, RestF} = {id(X bsl N + Acc =/= 0, TrUserData), Rest},
