skip_varint_StopResult(<<1:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> skip_varint_StopResult(Rest, Z1, Z2, F, F@_1, TrUserData);
skip_varint_StopResult(<<0:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> dfp_read_field_def_StopResult(Rest, Z1, Z2, F, F@_1, TrUserData).

skip_length_delimited_StopResult(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 57 -> skip_length_delimited_StopResult(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
